@ParameterizedTest
@ValueSource(strings = { "SIX", "EIGHT" })
void testRollbackMultipleAppendLogFilesInOneFileGroupInMOR(HoodieTableVersion tableVersion) throws Exception {
    Properties props = new Properties();
    props.put(HoodieTableConfig.VERSION.key(), tableVersion.versionCode());
    initMetaClient(tableType, props);
    String partition = "partA";
    HoodieSparkWriteableTestTable testTable = HoodieSparkWriteableTestTable.of(metaClient, addMetadataFields(RawTripTestPayload.JSON_DATA_SCHEMA));
    String fileId = UUID.randomUUID().toString();
    HoodieRecord tripRecord = new RawTripTestPayload("{\"_row_key\":\"key1\",\"time\":\"2016-01-31T03:16:41.415Z\",\"number\":12}").toHoodieRecord();
    String instantTime1 = "001";
    testTable.forCommit(instantTime1);
    StoragePath baseFilePath = testTable.withInserts(partition, fileId, Collections.singletonList(tripRecord));
    testTable.addDeltaCommit(instantTime1);
    assertTrue(storage.exists(baseFilePath));
    String instantTime2 = "002";
    testTable.forDeltaCommit(instantTime2).withLogFile(partition, fileId, tableVersion.greaterThanOrEquals(HoodieTableVersion.EIGHT) ? instantTime2 : instantTime1, 1);
    testTable.addDeltaCommit(instantTime2);
    String instantTime3 = "003";
    int numLogFiles = 199;
    Set<String> logFilePathSet = new HashSet<>();
    int[] logVersions = tableVersion.greaterThanOrEquals(HoodieTableVersion.EIGHT) ? IntStream.rangeClosed(1, numLogFiles).toArray() : IntStream.rangeClosed(2, numLogFiles + 1).toArray();
    String logFileInstantTime = tableVersion.greaterThanOrEquals(HoodieTableVersion.EIGHT) ? instantTime3 : instantTime1;
    testTable.forDeltaCommit(instantTime3).withLogFile(partition, fileId, logFileInstantTime, logVersions);
    for (int version : logVersions) {
        String logFileName = FileCreateUtils.logFileName(logFileInstantTime, fileId, version);
        StoragePath logFilePath = new StoragePath(new StoragePath(basePath, partition), logFileName);
        assertTrue(storage.exists(logFilePath));
        logFilePathSet.add(logFilePath.toString());
        testTable.withLogMarkerFile(partition, logFileName);
    }
    testTable.addInflightDeltaCommit(instantTime3);
    metaClient.reloadActiveTimeline();
    HoodieWriteConfig writeConfig = getConfig();
    writeConfig.setValue(ROLLBACK_PARALLELISM_VALUE, String.valueOf(logVersions.length));
    HoodieTable hoodieTable = HoodieSparkTable.create(getConfig(), context, metaClient);
    DirectWriteMarkers writeMarkers = mock(DirectWriteMarkers.class);
    MockitoAnnotations.openMocks(this);
    when(writeMarkers.allMarkerFilePaths()).thenThrow(new IOException("Markers.type file not present"));
    MarkerBasedRollbackStrategy rollbackStrategy = new MarkerBasedRollbackStrategy(hoodieTable, context, getConfig(), "004");
    HoodieInstant instantToRollback = INSTANT_GENERATOR.createNewInstant(HoodieInstant.State.INFLIGHT, HoodieTimeline.DELTA_COMMIT_ACTION, instantTime3);
    List<HoodieRollbackRequest> rollbackRequests = rollbackStrategy.getRollbackRequests(instantToRollback);
    assertEquals(tableVersion.greaterThanOrEquals(HoodieTableVersion.EIGHT) ? numLogFiles : 1, rollbackRequests.size());
    HoodieRollbackPlan rollbackPlan = new HoodieRollbackPlan(new HoodieInstantInfo(instantTime3, HoodieTimeline.DELTA_COMMIT_ACTION), rollbackRequests, LATEST_ROLLBACK_PLAN_VERSION);
    EmbeddedTimelineService timelineServer = EmbeddedTimelineServerHelper.createEmbeddedTimelineService(context, writeConfig);
    writeConfig.setViewStorageConfig(timelineServer.getRemoteFileSystemViewConfig(writeConfig));
    hoodieTable = HoodieSparkTable.create(writeConfig, context, metaClient);
    MergeOnReadRollbackActionExecutor rollbackActionExecutor = new MergeOnReadRollbackActionExecutor(context, writeConfig, hoodieTable, "004", instantToRollback, true, false);
    List<HoodieRollbackStat> rollbackStats = rollbackActionExecutor.doRollbackAndGetStats(rollbackPlan);
    timelineServer.stopForBasePath(basePath);
    assertEquals(1, rollbackStats.size());
    HoodieRollbackStat rollbackStat = rollbackStats.get(0);
    if (!tableVersion.greaterThanOrEquals(HoodieTableVersion.EIGHT)) {
        StoragePath rollbackLogPath = new StoragePath(new StoragePath(basePath, partition), FileCreateUtils.logFileName(instantTime1, fileId, numLogFiles + 2));
        assertTrue(storage.exists(rollbackLogPath));
        assertEquals(rollbackLogPath.getPathWithoutSchemeAndAuthority(), rollbackStat.getCommandBlocksCount().entrySet().stream().findFirst().get().getKey().getPath().getPathWithoutSchemeAndAuthority());
    }
    assertEquals(partition, rollbackStat.getPartitionPath());
    assertEquals(tableVersion.greaterThanOrEquals(HoodieTableVersion.EIGHT) ? numLogFiles : 0, rollbackStat.getSuccessDeleteFiles().size());
    if (tableVersion.greaterThanOrEquals(HoodieTableVersion.EIGHT)) {
        rollbackStat.getSuccessDeleteFiles().forEach(logFilePathSet::contains);
    }
    assertEquals(0, rollbackStat.getFailedDeleteFiles().size());
    assertEquals(tableVersion.greaterThanOrEquals(HoodieTableVersion.EIGHT) ? 0 : 1, rollbackStat.getCommandBlocksCount().size());
    assertEquals(tableVersion.greaterThanOrEquals(HoodieTableVersion.EIGHT) ? 0 : numLogFiles, rollbackStat.getLogFilesFromFailedCommit().size());
}

