private SeekableDataInputStream prepareMockedLogInputStream(int contentSize, int numReadFailTimes) throws IOException {
    IOException exception = new IOException("Read content from log file fails");
    Answer<Integer> mockedContentAnswer = modifyContentWithRead(contentSize);
    InputStream stream = mock(InputStream.class);
    switch(numReadFailTimes) {
        case 0:
            when(stream.read(any(), eq(0), eq(contentSize))).thenAnswer(mockedContentAnswer);
            break;
        case 1:
            when(stream.read(any(), eq(0), eq(contentSize))).thenThrow(exception).thenAnswer(mockedContentAnswer);
            break;
        case 2:
            when(stream.read(any(), eq(0), eq(contentSize))).thenThrow(exception).thenThrow(exception).thenAnswer(mockedContentAnswer);
            break;
        case 3:
            when(stream.read(any(), eq(0), eq(contentSize))).thenThrow(exception).thenThrow(exception).thenThrow(exception).thenAnswer(mockedContentAnswer);
            break;
        default:
            throw new IllegalArgumentException("This mock does not support more than 3 failed read calls");
    }
