    keyBasedBuffer.processDeleteRecord(anotherRecord, anotherMetadata);
    records = keyBasedBuffer.getLogRecords();
    assertEquals(2, records.size());
    assertEquals(Pair.of(Option.empty(), anotherMetadata), records.get("54321"));
}

