    props.put("hoodie.errortable.write.class", HoodieConfig.class.getName());
    assertThrows(HoodieException.class, () -> ErrorTableUtils.getErrorTableWriter(new HoodieStreamer.Config(), sparkSession, props, sparkContext, fileSystem, Option.empty()));
